/* Generated by `cargo xtask kernel` from merlin-as's tables (crates/merlin-as/src/encode.rs,
 * reloc.rs, elf.rs, section.rs) and excalibur's (opcodes, registers, CSRs): do not
 * edit. See crates/xtask/src/c_tables.rs. */
#ifndef AS_TABLES_H
#define AS_TABLES_H

/* A mnemonic and two fields (funct3, funct7). Tables end with a NULL name. */
struct as_op3 {
    const char *name;
    unsigned int a;
    unsigned int b;
};

/* A mnemonic, or a name, and one value. */
struct as_op2 {
    const char *name;
    unsigned int value;
};

/* Major opcodes, bits [6:0] (spec section 4). */
#define OPC_LUI 0x37
#define OPC_AUIPC 0x17
#define OPC_JAL 0x6f
#define OPC_JALR 0x67
#define OPC_BRANCH 0x63
#define OPC_LOAD 0x03
#define OPC_STORE 0x23
#define OPC_OP_IMM 0x13
#define OPC_OP_IMM_32 0x1b
#define OPC_OP 0x33
#define OPC_OP_32 0x3b
#define OPC_MISC_MEM 0x0f
#define OPC_SYSTEM 0x73
#define OPC_AMO 0x2f
#define OPC_CUSTOM_0 0x0b

/* funct3 values the pseudo-instructions use by name (CSR_IMM: the immediate CSR forms). */
#define F_ADDI 0
#define F_SLTIU 3
#define F_XORI 4
#define F_ANDI 7
#define F_SLLI 1
#define F_BEQ 0
#define F_BNE 1
#define F_BLT 4
#define F_BGE 5
#define F_BLTU 6
#define F_BGEU 7
#define F_CSRRW 1
#define F_CSRRS 2
#define F_CSRRC 3
#define F_CSR_IMM 4
#define F_SRLI 5
#define F_AMO_W 2
#define F_AMO_D 3

/* The encodings of the real instructions, by format (merlin-as's encode.rs); the
 * _32_ and _RV64_ ones are RV64's own, looked up only when assembling for RV64. */
extern const struct as_op3 OP_FUNCT[];
extern const struct as_op3 SHIFT_FUNCT[];
extern const struct as_op3 OP_32_FUNCT[];
extern const struct as_op3 SHIFT_32_FUNCT[];
extern const struct as_op2 OP_IMM_FUNCT3[];
extern const struct as_op2 LOAD_FUNCT3[];
extern const struct as_op2 STORE_FUNCT3[];
extern const struct as_op2 BRANCH_FUNCT3[];
extern const struct as_op2 CSR_FUNCT3[];
extern const struct as_op2 ATOMIC_FUNCT5[];
extern const struct as_op2 SYSTEM_FUNCT12[];
extern const struct as_op2 OP_IMM_32_FUNCT3[];
extern const struct as_op2 LOAD_RV64_FUNCT3[];
extern const struct as_op2 STORE_RV64_FUNCT3[];

/* Register ABI names, by number (and x0-x31, and fp for s0). */
extern const char *const REG_NAMES[32];

/* CSR names and numbers (excalibur's csr.rs): every one RV32 has, and those of them
 * only RV32 has, which are no name on RV64; and the counters' numbers. */
extern const struct as_op2 CSR_NAMES[];
extern const struct as_op2 CSR_RV32_ONLY[];
#define CSR_CYCLE 0xc00
#define CSR_TIME 0xc01
#define CSR_INSTRET 0xc02
#define CSR_CYCLEH 0xc80
#define CSR_TIMEH 0xc81
#define CSR_INSTRETH 0xc82

/* Section types and flags (merlin-as's section.rs). */
#define SHT_PROGBITS 0x1
#define SHT_NOTE 0x7
#define SHT_NOBITS 0x8
#define SHT_INIT_ARRAY 0xe
#define SHT_FINI_ARRAY 0xf
#define SHT_PREINIT_ARRAY 0x10
#define SHT_RISCV_ATTRIBUTES 0x70000003
#define SHF_WRITE 0x1
#define SHF_ALLOC 0x2
#define SHF_EXECINSTR 0x4
#define SHF_MERGE 0x10
#define SHF_STRINGS 0x20
#define SHF_TLS 0x400

/* `.section`'s flag letters, each a one-letter name, and its type names. */
extern const struct as_op2 SECTION_FLAGS[];
extern const struct as_op2 SECTION_TYPES[];

/* The sections LLVM has before the first line, with their type, flags and
 * entry size. The table ends with a NULL name. */
struct as_section {
    const char *name;
    unsigned int ty;
    unsigned int flags;
    unsigned int entsize;
};
extern const struct as_section PREDEFINED_SECTIONS[];

/* Relocation types (psABI numbers): what the assembler calls a fixup's kind too. */
#define R_RISCV_32 1
#define R_RISCV_64 2
#define R_RISCV_BRANCH 16
#define R_RISCV_JAL 17
#define R_RISCV_CALL_PLT 19
#define R_RISCV_PCREL_HI20 23
#define R_RISCV_PCREL_LO12_I 24
#define R_RISCV_PCREL_LO12_S 25
#define R_RISCV_HI20 26
#define R_RISCV_LO12_I 27
#define R_RISCV_LO12_S 28

/* Tag_RISCV_arch in every object's .riscv.attributes (merlin-as's elf.rs), by width. */
#define RISCV_ARCH "rv32i2p1_m2p0_a2p1_zicsr2p0_zifencei2p0_zmmul1p0_zaamo1p0_zalrsc1p0"
#define RISCV_ARCH_RV64 "rv64i2p1_m2p0_a2p1_zicsr2p0_zifencei2p0_zmmul1p0_zaamo1p0_zalrsc1p0"

#endif
